import { TaskAlreadyDoneError } from '../errors/DomainError';
import { DueDate } from '../value-objects/DueDate';
import { requireText } from '../value-objects/RequiredText';
import { TaskStatus } from '../value-objects/TaskStatus';

export interface TaskProps {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate: DueDate | null;
  status: TaskStatus;
}

export interface TaskCriteria {
  status?: TaskStatus;
  assigneeId?: string;
}

export class Task {
  readonly id: string;
  readonly projectId: string;
  readonly title: string;
  readonly description: string;
  readonly dueDate: DueDate | null;
  private currentStatus: TaskStatus;
  private currentAssigneeId: string | null = null;

  constructor(props: TaskProps) {
    this.id = props.id;
    this.projectId = props.projectId;
    this.title = requireText(props.title, 'Task title');
    this.description = props.description;
    this.dueDate = props.dueDate;
    this.currentStatus = props.status;
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | null {
    return this.currentAssigneeId;
  }

  assignTo(userId: string): void {
    this.currentAssigneeId = userId;
  }

  markDone(): void {
    if (this.currentStatus === 'done') {
      throw new TaskAlreadyDoneError(this.id);
    }
    this.currentStatus = 'done';
  }

  matches(criteria: TaskCriteria): boolean {
    if (criteria.status !== undefined && criteria.status !== this.currentStatus) {
      return false;
    }
    if (criteria.assigneeId !== undefined && criteria.assigneeId !== this.currentAssigneeId) {
      return false;
    }
    return true;
  }
}

=====SOURCE-END=====

